text:
{
  "questions": [
    {
      "n": 1,
      "start": "Qu'entreprend le canton",
      "end": "pour éviter une telle pollution ?"
    },
    {
      "n": 2,
      "start": "Comment se fait-il que ces déchets",
      "end": "se retrouvent aux abords de la route de montagne entre Miex et Tanay ?"
    },
    {
      "n": 3,
      "start": "Les entreprises de recyclage ont-elles",
      "end": "l'autorisation du canton d'utiliser comme remblais des matériaux de construction contenant des fibres plastiques ?"
    },
    {
      "n": 4,
      "start": "Existe-t-il une coordination entre les cantons",
      "end": "permettant de récupérer ces fibres plastiques sur les chantiers, d'exiger un meilleur recyclage auprès des sociétés mandatées ou simplement d'interdire cette technique tant que la récupération de ces fibres fait défaut ?"
    },
    {
      "n": 6,
      "start": "Comment le canton envisage-t-il d'assainir",
      "end": "les sites pollués par ces fibres plastiques provenant d'entreprises utilisant cette technique ?"
    },
    {
      "n": 5,
      "start": "Est-ce que cette méthode de béton projeté en fibres polymère",
      "end": "a-t-elle été utilisée lors de la construction d'autres tunnels dans notre canton ? si oui, est-ce que ces fibres ont-elles été découvertes dans les eaux ou les sols proche du chantier ?"
    }
  ],
  "answers": [
    {
      "n": 1,
      "start": "Auf der Baustelle des Tunnels von Les Evouettes wurde das ganze Abwasser, und damit",
      "end": "auch alle Fasern auf dem Baustellengelände, aufgefangen und behandelt."
    },
    {
      "n": 2,
      "start": "Das Unternehmen hat versehentlich Material an eine Baustelle an der Strasse nach Tanay",
      "end": "geliefert, das nicht behandelt und nicht für diesen Zweck vorgesehen war."
    },
    {
      "n": 3,
      "start": "Nach einem Gespräch zwischen der Dienststelle für Mobilität (DFM) und der Dienststelle",
      "end": "für Umwelt (DUW) wurde vereinbart, dass dieses Material in Form von Recycling-Kiessand P (mit über 95 % Naturgranulat) für Damm- oder Aufschüttungsarbeiten im Tiefbau verwertet werden darf."
    },
    {
      "n": 4,
      "start": "Es gab Gespräche zwischen den Vertretern aus dem Bereich «Abfälle» der Westschweizer",
      "end": "Kantone. Auf Ebene der bauenden Dienststellen gibt es unseres Wissens keine kantonsübergreifende Koordination in dieser Angelegenheit."
    },
    {
      "n": 6,
      "start": "Am Standort des Tunnels von Les Evouettes wurde das betroffene Material behandelt und",
      "end": "die Fasern vom Materialbewirtschafter entfernt."
    },
    {
      "n": 5,
      "start": "Abgesehen von der Baustelle des Tunnels von Les Evouettes gibt es derzeit in den Kreisen",
      "end": "der DFM keine laufenden Bauprojekte, bei denen Polypropylenfasern zum Einsatz kommen könnten."
    }
  ],
  "submitter": "Carole Morisod et Nathalie Cretton",
  "co_signatories": [],
  "recommendation": "none",
  "reasoning": null
}
